# patch_20261011_greentown_dual_domain.ps1
# Greentown Labs staff mail from both greentownlabs.com and greentownlabs.org.
#   src/lib/email/header-parser.ts : sender -> contact matches contacts.email,
#     contacts.email_secondary and app.contact_emails, and a sender on a sibling
#     domain of the same mail folder (chloe@.org -> contact chloe@.com).
#   src/lib/email/whitelist.ts : inbound gate also accepts email_secondary,
#     contact_emails and mail-folder pins (address or domain).
# Writes nothing unless every file still matches the reviewed original
# (LF-normalized SHA-256). Idempotent. ASCII output only.
$Repo = "C:\dev\mbg-project"
function Sha([string]$t) { $b = [System.Text.Encoding]::UTF8.GetBytes($t); $h = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b); ($h | ForEach-Object { $_.ToString("x2") }) -join "" }
$items = @(
  @{ Path = "src\lib\email\header-parser.ts"; Old = "8fad16685a3770b36a34bff37e16d4bd485e18445ca673c5b32d508acd83d966"; New = "80f22611ae03f11ca17b161e46cb9010f85b43ca4a51739c384e2a92e0c12b04"; B64 = "" },
  @{ Path = "src\lib\email\whitelist.ts"; Old = "ed9e5ccbce70115128d7cff8cd0f819b1603f0e1a6c66678c985fd3c99b160e1"; New = "df9dfadc956840bf532e0076dd3d7fa52b0c8876733553be6daaab1a57fc1620"; B64 = "" }
)
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (-not (Test-Path -LiteralPath $p)) { Write-Output ("ERROR missing " + $it.Path); return }
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -ne $it.Old -and $cur -ne $it.New) { Write-Output ("ERROR changed since review, not patched: " + $it.Path); return }
}
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -eq $it.New) { Write-Output ("SKIP  already patched " + $it.Path); continue }
  [System.IO.File]::WriteAllBytes($p, [System.Convert]::FromBase64String($it.B64))
  Write-Output ("PATCHED " + $it.Path)
}
Write-Output "DONE"
